(function(E){ const x = E["hr-m1"] = E["hr-m1"] || {units:{}}; x.units["hr-1-1"] = {"explain":{"id":"c-hr-1-1-e","course":"hr","unit":"hr-1-1","type":"explain","level":"B1","title":{"en":"My role, my team","tr":"Görevim, ekibim","fa":"نقش من، تیم من"},"objective":{"en":"After this lesson, you can describe your role and your team's work, and say what you are working on at the moment.","tr":"Bu dersin sonunda görevini ve ekibinin işini anlatabilir, şu anda ne üzerinde çalıştığını söyleyebileceksin.","fa":"بعد از این درس می‌توانی نقش خودت و کار تیمت را توضیح بدهی و بگویی این روزها مشغول چه کاری هستی."},"hook":{"en":"Tell a new team three facts about your work: role, team and current project. Then they know what to bring to you. Leyla's first take sounded like a bad translation. One small switch fixed it.","tr":"Yeni bir ekibe işinle ilgili üç bilgi ver: görev, ekip ve şu anki proje. Böylece sana hangi işlerle geleceklerini bilirler. Leyla'nın ilk denemesi kötü bir çeviri gibiydi. Küçük bir değişiklik her şeyi düzeltti.","fa":"به تیم جدید سه نکته درباره‌ی کارت بگو: نقش، تیم و پروژه‌ی فعلی. آن وقت می‌دانند برای چه کارهایی سراغت بیایند. اولین نسخه‌ی لیلا شبیه یک ترجمه‌ی بد بود. یک تغییر کوچک درستش کرد."},"before":{"en":"Introduce yourself to a new team in two or three lines: your role, your team and what you are working on this month.","tr":"Yeni bir ekibe kendini iki üç satırda tanıt: görevin, ekibin ve bu ay üzerinde çalıştığın iş.","fa":"خودت را در دو سه خط به یک تیم تازه معرفی کن: نقشت، تیمت و کاری که این ماه رویش کار می‌کنی."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"4"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Say what you do now","tr":"Şu an ne yaptığını söyle","fa":"بگو الان چه کار می‌کنی"},"body":{"en":"Your history can wait. People need three facts: your role, your team and your work this month. Then they know who you are and when to call you.","tr":"Geçmişin bekleyebilir. İnsanların üç bilgiye ihtiyacı var: görevin, ekibin ve bu ayki işin. Böylece kim olduğunu ve seni ne zaman arayacaklarını bilirler.","fa":"گذشته‌ات را بگذار برای بعد. دیگران سه چیز را باید بدانند: نقشت، تیمت و کار این ماهت. آن وقت می‌دانند تو کی هستی و کی باید با تو تماس بگیرند."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Role vs. current project","tr":"Görev ve şu anki proje","fa":"نقش ثابت و پروژه‌ی فعلی"},"steps":[{"en":"Your job, always true: present simple.","tr":"İşin, her zaman doğru olan: present simple.","fa":"برای شغلت و چیزی که همیشه درست است، حال ساده می‌آید.","ex":"I work in HR. I report to Omar."},{"en":"This month, this project: present continuous.","tr":"Bu ay, bu proje: present continuous.","fa":"برای این ماه و این پروژه، حال استمراری می‌آید.","ex":"I'm working on the Dubai plan."},{"en":"have, know, want, belong: no -ing when you state a fact.","tr":"have, know, want, belong: bir bilgi verirken -ing almaz.","fa":"⁨have⁩، ⁨know⁩، ⁨want⁩ و ⁨belong⁩: وقتی واقعیتی را می‌گویی، ⁨-ing⁩ نمی‌گیرند.","ex":"My team has six people."}],"table":{"headers":{"en":["Use","Pattern"],"tr":["Kullanım","Kalıp"],"fa":["کاربرد","الگو"]},"rows":[["My permanent role","I'm responsible for... / I report to..."],["What my team does","We recruit, train and support staff."],["Right now / this month","I'm working on... / We're hiring..."],["Not with -ing","have, know, want, belong"]]},"tip":{"en":"Turkish uses -yor for both ('İK'da çalışıyorum', 'plan üzerinde çalışıyorum') and Persian uses one present form for both. English splits them: I work in HR / I'm working on the plan.","tr":"Türkçede ikisi için de -yor kullanılır: 'İK'da çalışıyorum' ve 'Plan üzerinde çalışıyorum'. İngilizce bunları ayırır: kalıcı iş için I work, şu anki proje için I'm working.","fa":"در فارسی «کار می‌کنم» هم برای شغل ثابت می‌آید و هم برای کار این روزها. انگلیسی این دو را جدا می‌کند: «⁨I work in HR⁩» و «⁨I'm working on the plan⁩». اگر در فارسی بتوانی بگویی «دارم ... می‌کنم»، در انگلیسی معمولاً ⁨-ing⁩ لازم است."},"wrong":"I am working in HR. This month I work on the hiring plan.","right":"I work in HR. This month I'm working on the hiring plan."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"I'm responsible for...","meaning":{"en":"Says what your permanent job is.","tr":"Kalıcı görevini söyler.","fa":"نقش ثابت و همیشگی تو را می‌گوید."}},{"phrase":"I report to...","meaning":{"en":"Says who your manager is.","tr":"Yöneticini söyler.","fa":"می‌گوید مدیرت چه کسی است."}},{"phrase":"At the moment I'm working on...","meaning":{"en":"Says what is happening now.","tr":"Şu an olanı söyler.","fa":"می‌گوید این روزها مشغول چه کاری هستی."}},{"phrase":"head office","meaning":{"en":"The main office of a company.","tr":"genel merkez.","fa":"دفتر مرکزی"}},{"phrase":"headcount","meaning":{"en":"The number of people employed.","tr":"çalışan sayısı.","fa":"تعداد کارکنان؛ تعداد نیرو"}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"A short intro is the norm","tr":"Kısa tanıtım normaldir","fa":"معرفی کوتاه، عرفِ محیط کار است"},"body":{"en":"In international companies a short intro with your role, your team and one current project is normal on day one. Giving a long life story can feel strange. Keep it to three facts.","tr":"Uluslararası şirketlerde ilk gün rolünü, ekibini ve şu anki bir projeni anlatan kısa bir tanıtım normaldir. Uzun bir hayat hikâyesi garip karşılanabilir. Üç bilgiyle sınırlı tut.","fa":"در شرکت‌های بین‌المللی رسم است که روز اول خودت را کوتاه معرفی کنی: نقشت، تیمت و یک پروژه که الان رویش کار می‌کنی. تعریف کردن سرگذشت مفصل ممکن است عجیب به نظر برسد. به همین سه نکته بسنده کن."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از شرح حال طولانی تا سه نکته‌ی کوتاه"},"text":"Facts: You work in recruitment. Your team has six people. This month: a hiring plan.","item":"I studied business, then I worked in many companies, and I love people.","why":{"en":"Weak: long, and nobody learns what you do now. Strong: role, team, current work. Three short facts.","tr":"Zayıf: uzun ve kimse şu an ne yaptığını öğrenemiyor. Güçlü: görev, ekip, şu anki iş. Üç kısa bilgi.","fa":"نسخه‌ی اول طولانی است و کسی نمی‌فهمد الان چه کار می‌کنی. نسخه‌ی دوم سه نکته‌ی کوتاه دارد: نقش، تیم و کار فعلی."},"answer":"I'm responsible for recruitment. My team has six people. At the moment I'm working on a hiring plan.","cut":["I studied business","then I worked in many companies","and I love people"],"cutHint":{"en":"Tap what the new team does not need on day one.","tr":"Yeni ekibin ilk gün ihtiyaç duymadığı şeylere dokun.","fa":"روی چیزهایی بزن که تیم تازه روز اول لازمشان ندارد."}},"quick":{"prompt":"It is your first day in an international team. How long should your intro be?","options":["About three facts: role, team, current project","Your full career story, so they know you","Only your first name"],"correct":0,"why":{"en":"About three facts: on day one a short intro with your role, your team and one project is normal. A long life story can feel strange.","tr":"Yaklaşık üç bilgi: İlk gün görevin, ekibin ve bir projenle kısa bir tanıtım normaldir. Uzun bir hayat hikâyesi tuhaf gelebilir.","fa":"حدود سه نکته: روز اول معرفی کوتاه با نقشت، تیمت و یک پروژه عادی است. تعریف کردن داستان زندگی می‌تواند عجیب به نظر برسد."},"point":4},"remember":{"en":"Can you add 'this month' and still mean it? Then use -ing. Result of this lesson: you can introduce yourself in three facts. You also have your intro message.","tr":"Cümleye 'bu ay' ekleyince anlam aynı kalıyor mu? O zaman -ing kullan. Bu dersin sonucu: üç bilgiyle kendini tanıtabilirsin ve elinde tanıtım mesajın olur.","fa":"اگر بتوانی «این ماه» را به جمله اضافه کنی و معنی عوض نشود، ⁨-ing⁩ لازم است. حالا می‌توانی خودت را با سه نکته معرفی کنی. پیام معرفی‌ات هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Present perfect continuous for work in progress","tr":"Süren işler için present perfect continuous","fa":"حال کامل استمراری برای کار در جریان"},"steps":[{"en":"Started in the past, still going: have/has been + -ing.","tr":"Geçmişte başladı, hâlâ sürüyor: have/has been + -ing.","fa":"کاری که در گذشته شروع شده و هنوز ادامه دارد، با have/has been و فعل -ing‌دار می‌آید.","ex":"I've been working on the plan since August."},{"en":"since + the start point; for + the length of time.","tr":"since + başlangıç noktası; for + süre.","fa":"بعد از since نقطه‌ی شروع می‌آید و بعد از for مدت زمان.","ex":"since August / for two months"},{"en":"Ask about length with have you been + -ing.","tr":"Süreyi have you been + -ing ile sor.","fa":"برای پرسیدن مدت، از have you been و فعل -ing‌دار استفاده کن.","ex":"How long have you been working in HR?"}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Started in the past, still going","I've been working on the plan since August."],["Asking how long","How long have you been working in HR?"],["With for + a period","She's been leading the team for two years."]]},"body":{"en":"B2 track: in your intro (speaking and message), add one sentence with since or for in the present perfect continuous.","tr":"B2 yolu: tanıtımında (konuşma ve mesaj) since veya for ile present perfect continuous kullanan bir cümle ekle.","fa":"مسیر B2: در معرفی‌ات (هم در صحبت، هم در پیام نوشتاری) یک جمله با since یا for در زمان حال کامل استمراری بیاور."}}},"grammar":{"id":"c-hr-1-1-g","level":"B1","course":"hr","unit":"hr-1-1","title":"Role vs. current project","titleTr":"Görev ve şu anki proje","exp":{"en":"Use the present simple for what is always true about your job: \"I work in HR. I report to the HR director. My team has six people.\" Use the present continuous for what is happening around now, even if it is temporary: \"At the moment I'm working on the Dubai hiring plan.\" Stative verbs like have, know, want and belong almost never take -ing, so \"My team is having six people\" is wrong. Quick test: could you add \"this month\" and still mean it? Then use -ing. If it is your permanent role, use the simple form.","tr":"İşin hakkında her zaman doğru olanlar için present simple kullan: \"I work in HR. I report to the HR director. My team has six people.\" Şu anda ya da bu dönemde olan, geçici şeyler için present continuous kullan: \"At the moment I'm working on the Dubai hiring plan.\" Have, know, want, belong gibi durum fiilleri neredeyse hiç -ing almaz; bu yüzden \"My team is having six people\" yanlıştır. Kısa test: cümleye \"bu ay\" ekleyip aynı anlamı koruyabiliyor musun? O zaman -ing kullan. Kalıcı görevinden söz ediyorsan present simple kullan.","fa":"برای چیزهایی که همیشه درباره‌ی شغلت صدق می‌کند، از زمان حال ساده (⁨present simple⁩) استفاده کن: «⁨I work in HR. I report to the HR director. My team has six people.⁩» برای کاری که همین روزها در جریان است، حتی اگر موقتی باشد، حال استمراری (⁨present continuous⁩) به کار ببر؛ همان «دارم ... می‌کنم» فارسی: «⁨At the moment I'm working on the Dubai hiring plan.⁩» فعل‌های حالت، مثل ⁨have⁩، ⁨know⁩، ⁨want⁩ و ⁨belong⁩، تقریباً هیچ‌وقت ⁨-ing⁩ نمی‌گیرند؛ در فارسی هم نمی‌گوییم «تیمم دارد شش نفر دارد». پس «⁨My team is having six people⁩» غلط است. یک آزمون ساده: اگر بتوانی «این ماه» را به جمله اضافه کنی و معنی عوض نشود، ⁨-ing⁩ لازم است. اگر از نقش ثابتت حرف می‌زنی، شکل ساده را به کار ببر."},"formsTable":{"headers":{"en":["Use","Pattern"],"tr":["Kullanım","Kalıp"],"fa":["کاربرد","الگو"]},"rows":[["My permanent role","I'm responsible for... / I report to..."],["What my team does","We recruit, train and support staff."],["Right now / this month","I'm working on... / We're hiring..."],["Not with -ing","have, know, want, belong"]]},"wrong":"My team is having six people.","right":"My team has six people.","blank":{"sentence":"Right now, Leyla ___ the Dubai job ads.","word":"is writing","distractors":["writes","write"]},"wrong2":"I am reporting to the HR director every day of my career.","right2":"I report to the HR director.","blank2":{"sentence":"My team ___ six people.","word":"has","distractors":["is having","have"]},"expParts":{"hook":{"en":"Leyla's first take sounded like a bad translation. One small switch fixed it.","tr":"Leyla'nın ilk denemesi kötü bir çeviri gibiydi. Küçük bir değişiklik her şeyi düzeltti.","fa":"اولین نسخه‌ی لیلا شبیه یک ترجمه‌ی بد بود. یک تغییر کوچک درستش کرد."},"tryWhy":{"en":"has: your team's size is a fact about your job, not something happening this month.","tr":"has: ekibinin kaç kişi olduğu işinle ilgili kalıcı bir bilgi, bu ay olan bir şey değil.","fa":"جواب has است، چون تعداد اعضای تیمت یک واقعیت ثابت درباره‌ی شغلت است، نه اتفاقی که این ماه در جریان باشد."},"rule":[{"en":"Your job, always true: present simple.","tr":"İşin, her zaman doğru olan: present simple.","fa":"برای شغلت و چیزی که همیشه درست است، حال ساده می‌آید.","ex":"I work in HR. I report to Omar."},{"en":"This month, this project: present continuous.","tr":"Bu ay, bu proje: present continuous.","fa":"برای این ماه و این پروژه، حال استمراری می‌آید.","ex":"I'm working on the Dubai plan."},{"en":"have, know, want, belong: no -ing when you state a fact.","tr":"have, know, want, belong: bir bilgi verirken -ing almaz.","fa":"⁨have⁩، ⁨know⁩، ⁨want⁩ و ⁨belong⁩: وقتی واقعیتی را می‌گویی، ⁨-ing⁩ نمی‌گیرند.","ex":"My team has six people."}],"test":{"en":"Can you add 'this month' and still mean it? Then use -ing.","tr":"Cümleye 'bu ay' ekleyince anlam aynı kalıyor mu? O zaman -ing kullan.","fa":"اگر بتوانی «این ماه» را به جمله اضافه کنی و معنی عوض نشود، ⁨-ing⁩ لازم است."},"contrast":{"en":"Turkish uses -yor for both ('İK'da çalışıyorum', 'plan üzerinde çalışıyorum') and Persian uses one present form for both. English splits them: I work in HR / I'm working on the plan.","tr":"Türkçede ikisi için de -yor kullanılır: 'İK'da çalışıyorum' ve 'Plan üzerinde çalışıyorum'. İngilizce bunları ayırır: kalıcı iş için I work, şu anki proje için I'm working.","fa":"در فارسی «کار می‌کنم» هم برای شغل ثابت می‌آید و هم برای کار این روزها. انگلیسی این دو را جدا می‌کند: «⁨I work in HR⁩» و «⁨I'm working on the plan⁩». اگر در فارسی بتوانی بگویی «دارم ... می‌کنم»، در انگلیسی معمولاً ⁨-ing⁩ لازم است."}},"errorWatch":[{"find":["is having a team","am having a team","is having six","is having five","is having four","is having ten","is having people","am knowing","is knowing","are knowing","am wanting","am belonging","is belonging"],"fix":{"en":"have, know, want and belong take no -ing when you state a fact: 'My team has six people.'","tr":"have, know, want ve belong bir bilgi verirken -ing almaz: 'My team has six people.'","fa":"⁨have⁩، ⁨know⁩، ⁨want⁩ و ⁨belong⁩ وقتی واقعیتی را می‌گویی ⁨-ing⁩ نمی‌گیرند: «⁨My team has six people.⁩»"}},{"find":["am reporting to","is reporting to"],"fix":{"en":"If this is your permanent role, use the present simple: 'I report to the HR director.'","tr":"Kalıcı görevinse present simple kullan: 'I report to the HR director.'","fa":"اگر این نقش ثابت توست، حال ساده بنویس: «⁨I report to the HR director.⁩»"}}]},"b2":{"id":"c-hr-1-1-b2","level":"B2","track":"B2","course":"hr","unit":"hr-1-1","title":"Present perfect continuous for work in progress","titleTr":"Süren işler için present perfect continuous","exp":{"en":"When you describe work that started in the past and is still going on, B2 speakers use the present perfect continuous (have/has been + -ing) with for or since: \"I've been working on the Dubai hiring plan since August.\", \"How long have you been working in HR?\" It shows both the start and the fact that it is not finished. Do not use the present continuous with since or for: \"I am working here since 2021\" is a very common error for Turkish and Farsi speakers, because both languages use a present form here (\"2021'den beri burada çalışıyorum\", «از ۲۰۲۱ اینجا کار می‌کنم»). In English the bridge from past to now needs have been + -ing.","tr":"Geçmişte başlayıp hâlâ süren bir işi anlatırken B2 seviyesinde konuşanlar for veya since ile present perfect continuous (have/has been + -ing) kullanır: \"I've been working on the Dubai hiring plan since August.\", \"How long have you been working in HR?\" Bu yapı hem başlangıcı hem de işin bitmediğini gösterir. Since veya for ile present continuous kullanma: \"I am working here since 2021\" Türkçe konuşanların çok sık yaptığı bir hatadır, çünkü Türkçede burada şimdiki zaman kullanılır (\"2021'den beri burada çalışıyorum\"). İngilizcede geçmişten şimdiye uzanan köprü have been + -ing ister.","fa":"وقتی از کاری حرف می‌زنی که در گذشته شروع شده و هنوز ادامه دارد، در سطح ⁨B2⁩ از حال کامل استمراری (⁨present perfect continuous⁩) یعنی ⁨have/has been⁩ + ⁨-ing⁩ همراه با ⁨for⁩ یا ⁨since⁩ استفاده کن: «⁨I've been working on the Dubai hiring plan since August.⁩» یا «⁨How long have you been working in HR?⁩» این ساختار دو چیز را با هم نشان می‌دهد: کار از کی شروع شده و اینکه هنوز تمام نشده است. با ⁨since⁩ و ⁨for⁩ از حال استمراری معمولی استفاده نکن. جمله‌ی «⁨I am working here since 2021⁩» یکی از رایج‌ترین اشتباه‌های فارسی‌زبان‌هاست، چون در فارسی همین‌جا زمان حال می‌آوریم: «از سال ۲۰۲۱ اینجا کار می‌کنم». اما در انگلیسی، برای وصل کردن گذشته به حال، ⁨have been⁩ + ⁨-ing⁩ لازم است."},"formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["Started in the past, still going","I've been working on the plan since August."],["Asking how long","How long have you been working in HR?"],["With for + a period","She's been leading the team for two years."]]},"wrong":"I am working here since 2021.","right":"I have been working here since 2021.","blank":{"sentence":"I ___ on the hiring plan since August.","word":"have been working","distractors":["am working","work"]},"wrong2":"How long are you working in HR?","right2":"How long have you been working in HR?","blank2":{"sentence":"How long ___ you been working in HR?","word":"have","distractors":["are","did"]},"useIn":{"en":"B2 track: in your intro (speaking and message), add one sentence with since or for in the present perfect continuous.","tr":"B2 yolu: tanıtımında (konuşma ve mesaj) since veya for ile present perfect continuous kullanan bir cümle ekle.","fa":"مسیر B2: در معرفی‌ات (هم در صحبت، هم در پیام نوشتاری) یک جمله با since یا for در زمان حال کامل استمراری بیاور."},"exitItem":{"from":"hr-1-1","kind":"blank","prompt":"Omar ___ for the job list all morning.","options":["is waiting","has been waiting","waits"],"correct":1,"why":{"en":"has been waiting: 'all morning' plus an action still going on. 'Is waiting' doesn't show the time so far, and 'waits' is a habit.","tr":"has been waiting: 'all morning' ve hâlâ süren bir eylem. 'Is waiting' şimdiye kadarki süreyi göstermez; 'waits' alışkanlıktır.","fa":"has been waiting درست است، چون all morning با کاری می‌آید که هنوز ادامه دارد. is waiting مدت تا الان را نشان نمی‌دهد و waits عادت است."}},"expParts":{"hook":{"en":"Leyla started the Dubai plan in August and she is still on it. One tense says both.","tr":"Leyla Dubai planına ağustosta başladı ve hâlâ üzerinde. Tek bir zaman ikisini birden söyler.","fa":"لیلا برنامه‌ی دبی را از ماه اوت شروع کرده و هنوز رویش کار می‌کند. برای گفتن هر دو با هم، یک زمان کافی است."},"tryWhy":{"en":"have: 'been working' always needs have or has in front. 'Are you been' does not exist.","tr":"have: 'been working' önünde her zaman have ya da has ister. 'Are you been' diye bir yapı yok.","fa":"جواب have است، چون been working همیشه have یا has را پیش از خودش می‌خواهد. are you been در انگلیسی وجود ندارد."},"rule":[{"en":"Started in the past, still going: have/has been + -ing.","tr":"Geçmişte başladı, hâlâ sürüyor: have/has been + -ing.","fa":"کاری که در گذشته شروع شده و هنوز ادامه دارد، با have/has been و فعل -ing‌دار می‌آید.","ex":"I've been working on the plan since August."},{"en":"since + the start point; for + the length of time.","tr":"since + başlangıç noktası; for + süre.","fa":"بعد از since نقطه‌ی شروع می‌آید و بعد از for مدت زمان.","ex":"since August / for two months"},{"en":"Ask about length with have you been + -ing.","tr":"Süreyi have you been + -ing ile sor.","fa":"برای پرسیدن مدت، از have you been و فعل -ing‌دار استفاده کن.","ex":"How long have you been working in HR?"}],"test":{"en":"Is there since or for in the sentence? Then 'am working' is wrong: use have been working.","tr":"Cümlede since ya da for var mı? O zaman 'am working' yanlış; have been working kullan.","fa":"since یا for در جمله هست؟ پس «am working» غلط است؛ have been working بنویس."},"contrast":{"en":"Turkish and Persian use a present form here ('2021'den beri burada çalışıyorum'), so 'I am working here since 2021' feels natural. English needs have been + -ing for this bridge from past to now.","tr":"Türkçede burada şimdiki zaman kullanılır: '2021'den beri burada çalışıyorum'. Bu yüzden 'I am working here since 2021' doğal gelir, ama İngilizce geçmişten bugüne uzanan durum için have been + -ing ister.","fa":"در فارسی می‌گوییم «از ۲۰۲۱ اینجا کار می‌کنم» و فعل حال است؛ برای همین «I am working here since 2021» طبیعی به نظر می‌رسد. انگلیسی برای کاری که از گذشته تا امروز ادامه دارد have been و فعل -ing‌دار می‌خواهد."}},"errorWatch":[{"find":["am working here since","am working here for","am working in hr since","am working in hr for","is working here since","are working here since","how long are you working","how long is she working","how long is he working"],"fix":{"en":"With since or for, use have been + -ing: 'I have been working here since 2021.'","tr":"since ya da for ile have been + -ing kullan: 'I have been working here since 2021.'","fa":"با since یا for از have been و فعل -ing‌دار استفاده کن: «I have been working here since 2021.»"}}]},"vocab":{"id":"c-hr-1-1-v","level":"B1","category":"vocab","course":"hr","unit":"hr-1-1","goals":["career"],"title":{"en":"Role and Team","tr":"Görev ve Ekip","fa":"نقش و تیم"},"cards":[{"word":"be responsible for","sentence":"I'm responsible for recruitment in the Dubai branch.","gap":"I'm responsible for","accept":["i'm responsible for","i am responsible for","be responsible for"],"meaning":{"en":"To be the person who must do or manage something.","tr":"sorumlu olmak.","fa":"مسئولِ انجام یا اداره‌ی کاری بودن"}},{"word":"report to","sentence":"I report to the HR director in Istanbul.","meaning":{"en":"To have someone as your direct manager.","tr":"birine bağlı olmak, birine rapor vermek.","fa":"زیر نظر کسی کار کردن؛ به او گزارش دادن"}},{"word":"head office","sentence":"Our head office is in Istanbul.","meaning":{"en":"The main office of a company.","tr":"genel merkez.","fa":"دفتر مرکزی"}},{"word":"branch","sentence":"The new branch in Dubai opens in January.","meaning":{"en":"A local office of a bigger company.","tr":"şube.","fa":"شعبه"}},{"word":"recruit","sentence":"We recruit drivers, planners and office staff.","meaning":{"en":"To find and hire new employees.","tr":"işe almak.","fa":"جذب و استخدام نیرو"}},{"word":"onboarding","sentence":"Onboarding takes one week for every new hire.","meaning":{"en":"Helping a new employee settle into the job.","tr":"yeni çalışanı işe alıştırma.","fa":"فرایند ورود و آشناسازی کارمند جدید"}},{"word":"headcount","sentence":"The Dubai branch needs a headcount of twelve.","meaning":{"en":"The number of people employed.","tr":"çalışan sayısı.","fa":"تعداد کارکنان؛ تعداد نیرو"}},{"word":"at the moment","sentence":"At the moment I'm working on the hiring plan.","meaning":{"en":"Now, in this period.","tr":"şu anda, bu dönemde.","fa":"در حال حاضر؛ این روزها"}},{"word":"support","sentence":"We support managers with hiring and training.","meaning":{"en":"To help someone do their work.","tr":"desteklemek.","fa":"پشتیبانی کردن؛ کمک کردن به کار کسی"}},{"word":"colleague","sentence":"My colleagues in Dubai start work at 7 a.m.","gap":"colleagues","accept":["colleagues","colleague"],"meaning":{"en":"A person you work with.","tr":"iş arkadaşı.","fa":"همکار"}}]},"story":{"id":"c-hr-1-1-s","level":"B1","genre":"Workplace","course":"hr","unit":"hr-1-1","title":{"en":"Sixty Seconds","tr":"Altmış Saniye","fa":"شصت ثانیه"},"text":"On Monday morning, Leyla Karimi had a new title: HR specialist, Atlas Logistics. By ten o'clock she also had a problem.\n\nOmar, the operations manager in Dubai, had sent her one line. \"Twelve people by March. Send me a video so my team knows who you are.\"\n\nSixty seconds. Leyla sat in front of her laptop and stared at her face. \"Hello, my name is Leyla. I am working in HR. I am having a team of six...\" She stopped. It sounded like a bad translation.\n\nHer colleague Selin leaned over. \"Say what you do, then say what you're doing now. Two different things.\"\n\nLeyla tried again. \"Hello, I'm Leyla. I work in HR at our head office in Istanbul. I report to the HR director, and I'm responsible for recruitment. My team has six people. At the moment I'm working on the Dubai hiring plan, so you will see a lot of me this quarter.\"\n\nThe red light on the camera went off. It was not perfect, but it sounded like her.\n\nHalf an hour later Omar replied with one word and a thumb: \"Good.\" Leyla smiled. In Dubai, forty people she had never met now knew her name, and each one was wondering what HR would do for them.","vocab":[{"word":"stare at","en":"To look at something for a long time.","tr":"dik dik bakmak","fa":"خیره شدن به چیزی"},{"word":"lean over","en":"To bend your body towards something.","tr":"öne doğru eğilmek","fa":"به سمت کسی یا چیزی خم شدن"},{"word":"quarter","en":"Three months of a business year.","tr":"çeyrek (üç aylık dönem)","fa":"سه‌ماهه؛ یک فصل کاری"},{"word":"bad translation","en":"Words copied from another language that sound wrong.","tr":"kötü çeviri","fa":"ترجمه‌ی کلمه‌به‌کلمه و ناشیانه"},{"word":"title","en":"The name of your job.","tr":"unvan","fa":"عنوان شغلی"}],"quiz":[{"prompt":"What was wrong with Leyla's first try?","options":["She used \"am having\" for her team, which sounds unnatural","She spoke for too long","She forgot her name"],"correct":0},{"prompt":"Which sentence is about her permanent role?","options":["I'm working on the Dubai hiring plan.","I'm responsible for recruitment.","I'm recording a video."],"correct":1},{"prompt":"Choose the correct sentence.","options":["My team is having six people.","My team has six people.","My team have six people."],"correct":1},{"prompt":"How might the people in Dubai feel after the video?","options":["Curious, and a little hopeful about what HR will do","Angry at Omar","Sure that Leyla is not serious"],"correct":0}],"notice":{"en":"Leyla records her intro twice. The first version has one sentence that sounds like a bad translation. Can you spot it?","tr":"Leyla tanıtımını iki kez kaydediyor. İlk versiyonda kötü bir çeviri gibi duran bir cümle var. Bulabilir misin?","fa":"لیلا معرفی‌اش را دو بار ضبط می‌کند. در نسخه‌ی اول جمله‌ای هست که شبیه ترجمه‌ی بد است. می‌توانی پیدایش کنی؟"},"bridge":{"en":"The sentence Leyla fixed is this unit's grammar: what you always do vs what you are doing now. Next: see how it works.","tr":"Leyla'nın düzelttiği cümle bu dersin dilbilgisi: her zaman yaptığın iş ve şu an yaptığın iş. Sırada: nasıl çalıştığını gör.","fa":"جمله‌ای که لیلا درستش کرد، همان گرامر این درس است: کاری که همیشه می‌کنی و کاری که این روزها انجام می‌دهی. قدم بعد: ببین چطور کار می‌کند."}},"speaking":{"id":"hr-1-1","course":"hr","unit":"hr-1-1","topic":{"en":"Introducing Yourself to a New Team","tr":"Yeni Bir Ekibe Kendini Tanıtmak","fa":"معرفی خودت به یک تیم تازه"},"warmup":{"en":"Who in your company does not know what your job is? What would they ask you?","tr":"Şirketinde işinin ne olduğunu bilmeyen kim var? Sana ne sorardı?","fa":"در شرکت تو چه کسی دقیقاً نمی‌داند کارت چیست؟ اگر بپرسد، چه سؤالی از تو می‌کند؟"},"questions":[{"en":"What is your role, and who do you report to?","tr":"Görevin nedir ve kime bağlısın?","fa":"نقش تو چیست و زیر نظر چه کسی کار می‌کنی؟"},{"en":"What does your team do for the rest of the company?","tr":"Ekibin şirketin geri kalanı için ne yapıyor?","fa":"تیم تو برای بقیه‌ی بخش‌های شرکت چه کار می‌کند؟"},{"en":"What are you working on at the moment?","tr":"Şu anda neyin üzerinde çalışıyorsun?","fa":"این روزها روی چه پروژه‌ای کار می‌کنی؟"},{"en":"How can colleagues contact you, and when?","tr":"İş arkadaşların sana nasıl ve ne zaman ulaşabilir?","fa":"همکاران چطور و چه موقع می‌توانند با تو تماس بگیرند؟"}],"followups":[{"en":"Say your answer out loud in 90 seconds, then 60, then 45. Keep the same three facts each time.","tr":"Cevabını yüksek sesle söyle: önce 90 saniyede, sonra 60, sonra 45 saniyede. Her seferinde aynı üç bilgiyi koru.","fa":"پاسخت را با صدای بلند بگو: یک بار در ۹۰ ثانیه، بعد در ۶۰ ثانیه و در آخر در ۴۵ ثانیه. هر بار همان سه نکته را بگو."},{"en":"Now introduce yourself and your real role, or the role you want, in two sentences.","tr":"Şimdi kendini ve gerçek görevini ya da istediğin görevi iki cümleyle tanıt.","fa":"حالا خودت و نقش واقعی‌ات، یا نقشی را که می‌خواهی، در دو جمله معرفی کن."}],"expressions":[{"phrase":"I'm responsible for...","meaning":{"en":"Says what your permanent job is.","tr":"Kalıcı görevini söyler.","fa":"نقش ثابت و همیشگی تو را می‌گوید."}},{"phrase":"I report to...","meaning":{"en":"Says who your manager is.","tr":"Yöneticini söyler.","fa":"می‌گوید مدیرت چه کسی است."}},{"phrase":"At the moment I'm working on...","meaning":{"en":"Says what is happening now.","tr":"Şu an olanı söyler.","fa":"می‌گوید این روزها مشغول چه کاری هستی."}}],"culture":{"en":"In international companies a short intro with your role, your team and one current project is normal on day one. Giving a long life story can feel strange. Keep it to three facts.","tr":"Uluslararası şirketlerde ilk gün rolünü, ekibini ve şu anki bir projeni anlatan kısa bir tanıtım normaldir. Uzun bir hayat hikâyesi garip karşılanabilir. Üç bilgiyle sınırlı tut.","fa":"در شرکت‌های بین‌المللی رسم است که روز اول خودت را کوتاه معرفی کنی: نقشت، تیمت و یک پروژه که الان رویش کار می‌کنی. تعریف کردن سرگذشت مفصل ممکن است عجیب به نظر برسد. به همین سه نکته بسنده کن."},"model":"Hi everyone, I'm Leyla Karimi. I work in HR at our head office in Istanbul, and I report to the HR director. I'm responsible for recruitment, and my team has six people. At the moment I'm working on the Dubai hiring plan, so you'll hear from me a lot this quarter. You can email me any time, or call me between nine and five.","selfCheck":[{"en":"I said my role with 'responsible for'.","tr":"Görevimi 'responsible for' ile söyledim.","fa":"نقشم را با «responsible for» گفتم."},{"en":"I said who I report to.","tr":"Kime bağlı çalıştığımı söyledim.","fa":"گفتم به چه کسی گزارش می‌دهم."},{"en":"I used 'at the moment' for a current project.","tr":"Şu anki proje için 'at the moment' kullandım.","fa":"برای پروژه‌ی فعلی از «at the moment» استفاده کردم."},{"en":"Round 3 fitted in 45 seconds.","tr":"3. tur 45 saniyeye sığdı.","fa":"دور سوم در ۴۵ ثانیه تمام شد."}]},"writing":{"id":"c-hr-1-1-w","title":{"en":"Your intro message to the team","tr":"Ekibe tanışma mesajın","fa":"پیام معرفی تو به تیم"},"course":"hr","unit":"hr-1-1","type":"writing","difficulty":"easy","prompt":{"en":"Write a 3-line intro message to the Dubai team: your role, your team and what you are working on this month. Use your own real job or Leyla's.","tr":"Dubai ekibine 3 satırlık bir tanışma mesajı yaz: görevin, ekibin ve bu ay üzerinde çalıştığın şey. Kendi gerçek işini ya da Leyla'nınkini kullan.","fa":"یک پیام معرفی سه‌خطی برای تیم دبی بنویس: نقشت، تیمت و کاری که این ماه رویش کار می‌کنی. می‌توانی از شغل واقعی خودت بنویسی یا از شغل لیلا."},"model":"Hi everyone, I'm Leyla. I work in HR at our head office in Istanbul and I'm responsible for recruitment. At the moment I'm working on the hiring plan for the Dubai branch, so please send me your questions.","frame":"Hi everyone, I'm ___. I work in ___ at ___ and I'm responsible for ___. At the moment I'm working on ___, so please ___.","words":[{"word":"responsible for"},{"word":"at the moment"},{"word":"team"}],"minWords":30,"minSentences":3,"rubric":["Task done: role, team, current project","Organised: 3 clear lines","Language: simple for the role, continuous for the project","Tone: friendly and professional"],"rubricI18n":{"tr":["Görev: rol, ekip, şu anki proje","Düzen: 3 net satır","Dil: rol için present simple, proje için present continuous","Üslup: samimi ve profesyonel"],"fa":["کامل بودن کار: نقش، تیم، پروژه‌ی فعلی","نظم: سه سطر روشن","زبان: حال ساده برای نقش، حال استمراری برای پروژه","لحن: دوستانه و حرفه‌ای"]},"portfolio":null,"parts":[{"t":{"en":"Your role","tr":"Görevin","fa":"نقش تو"},"find":["responsible for","i work in","i work as","my job is","in charge of","i manage"],"sample":"HR at the head office in Istanbul, responsible for recruitment"},{"t":{"en":"Your team","tr":"Ekibin","fa":"تیم تو"},"find":["team","department","office","colleagues"],"sample":"a team of six at the head office"},{"t":{"en":"What you are working on now","tr":"Şu an üzerinde çalıştığın iş","fa":"کاری که الان رویش کار می‌کنی"},"find":["at the moment","this month","currently","working on","right now"],"sample":"the hiring plan for the Dubai branch"}]},"perspective":{"id":"c-hr-1-1-p","title":{"en":"Through a new Dubai hire's eyes","tr":"Dubai'deki yeni bir çalışanın gözünden","fa":"از نگاه یک کارمند تازه‌وارد در دبی"},"course":"hr","unit":"hr-1-1","type":"perspective","minSentences":2,"prompt":{"en":"You are a new employee in Dubai who has just watched Leyla's sixty-second intro video. Write 2 sentences in first person: what do you hope HR will do for you?","tr":"Dubai'de Leyla'nın altmış saniyelik tanıtım videosunu az önce izlemiş yeni bir çalışansın. Birinci tekil şahısla 2 cümle yaz: İK'nın senin için ne yapmasını umuyorsun?","fa":"تو کارمند تازه‌واردی در دبی هستی و همین حالا ویدیوی شصت‌ثانیه‌ای معرفی لیلا را دیده‌ای. از زبان خودت دو جمله بنویس: امیدواری واحد منابع انسانی چه کاری برایت بکند؟"}},"exit":{"id":"c-hr-1-1-x","course":"hr","unit":"hr-1-1","type":"exit","note":"First unit: no earlier units, so all 6 items are from this unit. Later exits mix new + spaced via the from field.","items":[{"from":"hr-1-1","kind":"blank","prompt":"At the moment Leyla ___ for two new drivers.","options":["looks","is looking","look"],"correct":1,"point":2,"why":{"en":"is looking: 'at the moment' points to something happening now, so use am/is/are + -ing. 'Looks' is a habit, and 'look' doesn't agree with Leyla.","tr":"is looking: 'at the moment' şu anda olan bir şeyi gösterir, bu yüzden am/is/are + -ing. 'Looks' alışkanlıktır; 'look' Leyla ile uyuşmaz.","fa":"is looking درست است، چون at the moment یعنی همین الان در جریان است و am/is/are و فعل ing‌دار لازم است. looks عادت است و look با Leyla جور نیست."}},{"from":"hr-1-1","kind":"blank","prompt":"Atlas Logistics ___ offices in Istanbul and Dubai.","options":["is having","has","have"],"correct":1,"point":2,"why":{"en":"has: 'have' for owning something is a state, so it stays in the present simple. 'Is having' is wrong for a state, and 'have' doesn't agree with one company.","tr":"has: sahip olmak anlamındaki 'have' bir durumdur, geniş zamanda kalır. 'Is having' durum için yanlıştır; 'have' tek bir şirketle uyuşmaz.","fa":"has درست است، چون have به معنی داشتن حالت است و در حال ساده می‌ماند. is having برای حالت غلط است و have با یک شرکت جور نیست."}},{"from":"hr-1-1","kind":"blank","prompt":"I ___ to the HR director. (my permanent manager)","options":["report","am reporting","reporting"],"correct":0,"point":2,"why":{"en":"report: a permanent fact about your job takes the present simple. 'Am reporting' sounds temporary, and 'reporting' has no verb.","tr":"report: işinle ilgili kalıcı bir bilgi geniş zaman alır. 'Am reporting' geçici duyulur; 'reporting'te fiil yoktur.","fa":"report درست است، چون واقعیت دائمی درباره‌ی شغل حال ساده می‌خواهد. am reporting موقتی به نظر می‌رسد و reporting فعل ندارد."}},{"from":"hr-1-1","kind":"mcq","prompt":"Which phrase says who your manager is?","options":["I report to...","I'm responsible for...","At the moment I'm working on..."],"correct":0,"point":3,"why":{"en":"'I report to...' names your manager. 'I'm responsible for' gives your tasks, and 'At the moment I'm working on' gives your project.","tr":"'I report to...' yöneticinin adını söyler. 'I'm responsible for' görevlerini, 'At the moment I'm working on' projeni anlatır.","fa":"«I report to...» مدیرت را معرفی می‌کند. «I'm responsible for» وظیفه‌هایت را می‌گوید و «At the moment I'm working on» پروژه‌ات را."},"hint2":{"en":"One phrase names your manager, one your duties and one your current work. Which one is about the person above you?","tr":"Bir ifade yöneticini, biri görevlerini, biri de şu anki işini söyler. Hangisi senin üstündeki kişiyle ilgili?","fa":"یک عبارت مدیرت را می‌گوید، یکی وظیفه‌هایت را و یکی کار فعلی‌ات را. کدام درباره‌ی کسی است که بالادست توست؟"}},{"from":"hr-1-1","kind":"mcq","prompt":"Which sentence is about a temporary project?","options":["We have a head office in Istanbul.","We're hiring twelve drivers this quarter.","I know the HR director."],"correct":1,"point":2,"why":{"en":"'We're hiring twelve drivers this quarter' is temporary, so it takes the present continuous. A head office and knowing someone are permanent facts.","tr":"'We're hiring twelve drivers this quarter' geçicidir, bu yüzden present continuous alır. Genel merkez ve birini tanımak kalıcı bilgilerdir.","fa":"«We're hiring twelve drivers this quarter» موقتی است و حال استمراری می‌خواهد. دفتر مرکزی و شناختن کسی واقعیت‌های دائمی‌اند."}},{"from":"hr-1-1","kind":"mcq","prompt":"\"Headcount\" means...","options":["the number of people employed","a head of department","a job title"],"correct":0,"point":3,"why":{"en":"Headcount is the number of people employed. A head of department is a person, and a job title is a name for a role.","tr":"Headcount çalışan kişi sayısıdır. Head of department bir kişidir; job title bir görevin adıdır.","fa":"headcount یعنی تعداد کارکنان. head of department یک نفر است و job title اسم یک سمت."}},{"from":"hr-1-1","kind":"mcq","prompt":"In a first intro, why say your role before anything else?","options":["It tells people what to ask you about.","It shows how long you have worked.","It sounds more formal."],"correct":0,"why":{"en":"It tells people what to ask you about: your role says who you are and when to call you. Your history can wait.","tr":"İnsanlara sana ne soracaklarını söyler: Görevin kim olduğunu ve sana ne zaman başvuracaklarını gösterir. Geçmişin bekleyebilir.","fa":"به بقیه می‌گوید چه چیزی را از تو بپرسند: نقشت نشان می‌دهد کی هستی و کی باید سراغت بیایند. سابقه‌ات می‌تواند صبر کند."},"point":1}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
